import java.util.*;
public final class HF45RewardConfigCheck {
 static int checks;
 static void ok(boolean pass,String msg){if(!pass)throw new AssertionError(msg);checks++;}
 public static void main(String[] args)throws Exception{
  var original=RewardSettings.active;
  var draft=RewardSettings.validate(Json.obj(Json.parse(Json.write(RewardSettings.defaults()))));
  for(boolean tribal:new boolean[]{false,true})for(int d=0;d<4;d++){var c=RewardSettings.row(tribal,d);int[] count=new int[5];for(int r=0;r<100;r++)count[RewardSettings.grade(c,r)-1]++;ok(Arrays.equals(count,StoneDrops.WEIGHTS[Math.min(2,d)]),"default probabilities unchanged");}
  var store=new CloudStore.Memory();store.register("rewardconfig@local.test","test-password-123","Reward config test");var p=store.profile(store.login("rewardconfig@local.test","test-password-123").userId);p.experience=Progression.experienceForLevel(70);p.dungeonClear=true;
  var players=List.<Map<String,Object>>of(Map.of("id",p.id,"team",0));
  for(int d=0;d<4;d++){for(int stage=1;stage<=2;stage++){String match=UUID.randomUUID().toString();if(stage==1)store.finishAntStage(match,0,players,Math.min(2,d));else store.finishDungeon780(match,0,players,Math.min(2,d));int before=p.protectionCharms;var reward=store.claimDungeon(match,p.id,0,0,d);var c=RewardSettings.row(false,d);ok(reward[2]>=3&&reward[2]<=25,"ant quantity");int awarded=p.protectionCharms-before;ok(awarded>=RewardSettings.n(c,"protectMin")&&awarded<=RewardSettings.n(c,"protectMax"),"ant protection");ok(Arrays.equals(reward,store.claimDungeon(match,p.id,0,0,d))&&p.protectionCharms==before+awarded,"ant receipt");if(stage==2){store.claimDungeon(match,p.id,1,1,d);ok(p.protectionCharms==before+awarded,"ant no duplicate stage bonus");}}}
  for(int d=0;d<4;d++){for(int stage:new int[]{1,2,4}){String match=UUID.randomUUID().toString();var c=RewardSettings.row(true,d);var req=Map.<String,Object>of("match",match,"run",UUID.randomUUID().toString(),"stage",stage,"difficulty",Math.min(2,d),"winner",0,"players",players,"min",RewardSettings.n(c,"stoneMin"),"max",RewardSettings.n(c,"stoneMax"),"config",c);store.tribal("finish",req);int[] deck=store.tribalDeck(match);int rare=0;for(int i:deck)if(i==2)rare++;ok(rare==(stage==4&&d>=2?1:0),"rare odds");int card=0;while(deck[card]!=0)card++;int before=p.protectionCharms;var claim=Map.<String,Object>of("match",match,"user",p.id,"pick",0,"card",card);var result=store.tribal("claim",claim);int amount=Json.num(result,"amount",0);ok(amount>=RewardSettings.n(c,"stoneMin")&&amount<=RewardSettings.n(c,"stoneMax"),"tribal quantity");int bonus=p.protectionCharms-before;ok(bonus>=RewardSettings.n(c,"protectMin")&&bonus<=RewardSettings.n(c,"protectMax"),"tribal protection");ok(store.tribal("claim",claim).equals(result)&&p.protectionCharms==before+bonus,"tribal receipt");store.tribal("claim",Map.of("match",match,"user",p.id,"pick",1,"card",(card+1)%18));ok(p.protectionCharms==before+bonus,"tribal no duplicate stage bonus");}}
  var g=Json.obj(draft.get("gift"));g.put("stoneMin",12);g.put("stoneMax",12);g.put("vipChance",0);RewardSettings.active=RewardSettings.validate(draft);p.giftBags=1;var gift=store.giftOpen(p.id,1,"rewardtest");ok(Arrays.equals(gift,new int[]{3,12}),"configured gift");ok(Arrays.equals(gift,store.giftOpen(p.id,1,"rewardtest"))&&p.giftBags==0,"gift receipt");RewardSettings.active=original;
  Json.obj(draft.get("ant0")).put("grade1",0);try{RewardSettings.validate(draft);throw new AssertionError("invalid total accepted");}catch(IllegalArgumentException expected){checks++;}
  System.out.println("PASS "+checks+" reward config, odds, quantity, stage bonus, retry checks");
 }
}
